import 'dart:async'; import 'package:flutter/foundation.dart'; import 'package:permission_handler/permission_handler.dart'; import 'package:uuid/uuid.dart'; import '../models/emergency.dart'; import '../models/helmet_event.dart'; import '../services/location_service.dart'; import '../services/sms_service.dart'; import '../services/storage.dart';
class EmergencyController extends ChangeNotifier { EmergencyController(this.storage,this.location,this.sms,{this.countdownSeconds=15}); final Storage storage; final LocationService location; final SmsService sms; final int countdownSeconds; final _seen=<String>[]; EmergencyState state=EmergencyState.idle; int seconds=0; String? kind; Timer? _timer; int _run=0;
 bool get _active=>state==EmergencyState.countdown||state==EmergencyState.acquiringLocation||state==EmergencyState.sending;
 Future<void> start(HelmetEvent e,{bool test=false}) async {final id=e.eventId??const Uuid().v4();if(_seen.contains(id)||_active)return;_seen.add(id);if(_seen.length>100)_seen.removeAt(0);_timer?.cancel();final run=++_run;kind=test?'TEST ALERT':e.type==HelmetEventType.accident?'ACCIDENT':'MANUAL SOS';state=EmergencyState.countdown;seconds=countdownSeconds;notifyListeners();_timer=Timer.periodic(const Duration(seconds:1),(t){if(run!=_run){t.cancel();return;}seconds--;notifyListeners();if(seconds<=0){t.cancel();_dispatch(test,run);}});}
 Future<void> manual({bool test=false})=>start(HelmetEvent(HelmetEventType.manualSos,eventId:const Uuid().v4()),test:test);
 Future<void> cancel() async {if(state!=EmergencyState.countdown)return;_run++;_timer?.cancel();state=EmergencyState.cancelled;notifyListeners();await storage.addEvent(EventRecord(type:kind??'Alert',status:'Cancelled',time:DateTime.now(),locationAvailable:false,recipients:0,locationSource:'unavailable'));}
 Future<void> _dispatch(bool test,int run) async {if(run!=_run)return;state=EmergencyState.acquiringLocation;notifyListeners();final l=await location.current();if(run!=_run)return;state=EmergencyState.sending;notifyListeners();final contacts=storage.contacts().where((c)=>c.enabled&&c.isValid).toList();final permitted=await Permission.sms.request().isGranted;var ok=0;if(permitted){final body=EmergencyMessageBuilder().build(type:kind??'Emergency',time:DateTime.now(),latitude:l.latitude,longitude:l.longitude,test:test);for(final c in contacts){if(run!=_run)return;if((await sms.send(c.phone,body)).accepted)ok++;}}if(run!=_run)return;state=ok==contacts.length&&ok>0?EmergencyState.requested:ok>0?EmergencyState.partialFailure:EmergencyState.failed;await storage.addEvent(EventRecord(type:kind??'Emergency',status:state.name,time:DateTime.now(),locationAvailable:l.available,recipients:ok,locationSource:l.source ?? 'unavailable'));notifyListeners();}
 @override void dispose(){_timer?.cancel();super.dispose();}
}
